// Deux entrées : un bouton pressé dans Telegram, ou le Débogueur automatique qui demande une correction pour un workflow inscrit.
const j = $input.first().json, q = j.callback_query || {};
// Les conversations Telegram qui ont le droit de décider : votre identifiant de conversation.
const AUTORISES = ['VOTRE_IDENTIFIANT_TELEGRAM'];
// Les seuls workflows que ce débogueur a le droit de corriger, et seulement après votre appui.
const CORRECTION_AUTORISEE = ['ID_DU_WORKFLOW'];
// Parmi eux, ceux où il publie seul les nouvelles tentatives, sans attendre votre appui. Liste vide : tout reste sur validation.
const CORRECTION_AUTOMATIQUE = [];
const commun = { correction_autorisee: CORRECTION_AUTORISEE, correction_automatique: CORRECTION_AUTOMATIQUE, adresse_n8n: 'https://votre-instance-n8n' };
// C'est le déclencheur qui dit d'où vient la demande, jamais un champ reçu : un message Telegram ne peut pas se faire passer pour le débogueur.
let demande = false; try { demande = $('Quand le débogueur demande une correction').isExecuted === true; } catch (e) {}
if (demande) return [{ json: Object.assign({ valide: !!j.cle, automatique: true, action: { t: 'tentatives', d: 'delai' }[j.geste] || '', cle: String(j.cle || ''), requete: '', chat: AUTORISES[0] }, commun) }];
const m = /^dbg\|([rpntda])\|(.+)$/.exec(String(q.data || ''));
const chat = q.message && q.message.chat ? String(q.message.chat.id) : '';
return [{ json: Object.assign({ valide: !!m && AUTORISES.indexOf(chat) >= 0, automatique: false, action: m ? { r: 'relancer', p: 'pause', n: 'rien', t: 'tentatives', d: 'delai', a: 'annuler' }[m[1]] : '', cle: m ? m[2] : '', requete: String(q.id || ''), chat: chat }, commun) }];

// La décision vient d'une personne, ou d'une règle pour un workflow inscrit. Le débogueur vérifie qu'elle a encore un sens, et qu'il a le droit de l'exécuter.
const d = $('Lire la demande').first().json, l = $input.first().json || {};
const memoire = $getWorkflowStaticData('global'), corrections = memoire.corrections || {}, annulees = memoire.annulees || {};
const correction = ['tentatives', 'delai', 'annuler'].indexOf(d.action) >= 0;
let refus = '';
if (!d.valide) refus = 'Bouton non reconnu.';
else if (!l.cle) refus = 'Cette panne est introuvable dans le journal.';
else if (d.automatique && d.action !== 'tentatives') refus = 'Seules les nouvelles tentatives se publient sans validation.';
else if (l.etat === 'réparé' && (d.action === 'relancer' || d.action === 'pause')) refus = 'Cette panne est déjà réparée : rien à faire.';
else if (d.action === 'relancer' && !l.execution_id) refus = "Pas d'exécution à relancer pour cette panne.";
else if (correction && d.correction_autorisee.indexOf(String(l.workflow_id || '')) < 0) refus = "Ce workflow n'est pas inscrit pour les corrections : je n'y touche pas.";
else if (correction && d.action !== 'annuler' && ['service indisponible', 'trop de requêtes'].indexOf(l.famille) < 0) refus = 'Aucune correction simple ne correspond à cette panne.';
else if (d.automatique && d.correction_automatique.indexOf(String(l.workflow_id || '')) < 0) refus = "Ce workflow n'est pas inscrit pour la correction automatique.";
else if (d.automatique && l.etat !== 'réparé') refus = "La relance n'a pas réparé la panne : pas de correction sans validation.";
else if (d.automatique && annulees[l.workflow_id + '|' + l.etape]) refus = 'Une personne a annulé cette correction sur cette étape : elle ne se republie plus sans validation.';
else if (correction && d.action !== 'annuler' && corrections[d.cle]) refus = 'Cette correction est déjà publiée.';
else if (d.action === 'annuler' && !corrections[d.cle]) refus = 'Aucune correction à annuler pour cette panne.';
return [{ json: Object.assign({}, d, { quoi: refus ? 'refus' : correction ? 'corriger' : d.action, geste: correction ? d.action : '', refus: refus, execution_id: l.execution_id || '', workflow_id: l.workflow_id || '', workflow: l.workflow || '', etape: l.etape || '', etat_avant: l.etat || '', relance_avant: l.relance_id || '', action_avant: l.action || '' }) }];

// Ce qui a été fait, dit simplement, puis noté au journal. Une correction n'est annoncée que si n8n la confirme à la relecture, qu'elle vienne d'un bouton ou d'une demande du débogueur.
const d = $('Vérifier la demande').first().json, r = $input.first().json || {};
const esc = t => String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lu = n => { try { return $(n).isExecuted ? $(n).first().json : null; } catch (e) { return null; } };
const motif = e => String((e && (e.message || e.description)) || e || 'Raison inconnue.').slice(0, 300);
let action = '', etat = d.etat_avant, relance = d.relance_avant, texte = '', annulable = false;
if (d.quoi === 'relancer') {
  if (r.status === 'success' || r.finished === true) { etat = 'réparé'; relance = String(r.id || ''); action = 'relancé à la demande depuis Telegram, allé au bout' + (r.id ? ' (exécution ' + r.id + ')' : ''); texte = '🟢 <b>Relancé : « ' + esc(d.workflow) + ' » est allé au bout</b>' + (r.id ? '\nExécution ' + r.id + '.' : ''); }
  else if (r.error) { texte = '🟠 <b>Relance impossible</b>\n' + esc(motif(r.error).slice(0, 200)); }
  else { action = 'relancé à la demande depuis Telegram, la panne est toujours là'; texte = '🟠 <b>Relancé, mais la panne est toujours là</b>\n« ' + esc(d.workflow) + ' » : la cause reste à corriger.'; }
} else if (d.quoi === 'pause') {
  if (r.active === false) { action = 'mis en pause à la demande depuis Telegram'; texte = '⏸ <b>« ' + esc(d.workflow) + ' » est en pause</b>\nRien n\'est supprimé. Republiez-le dans n8n quand la cause est corrigée.'; }
  else texte = '🟠 <b>Mise en pause impossible</b>\nn8n n\'a pas confirmé l\'arrêt.';
} else if (d.quoi === 'corriger') {
  const prep = lu('Préparer la correction') || {}, relu = lu('Relire le workflow'), memoire = $getWorkflowStaticData('global');
  memoire.corrections = memoire.corrections || {}; memoire.annulees = memoire.annulees || {};
  // Une publication automatique annulée par une personne ne se refait plus sans elle sur cette étape. Si elle publie la correction elle-même plus tard, la réserve tombe.
  const cleEtape = d.workflow_id + '|' + prep.etape, seule = !!(memoire.corrections[d.cle] || {}).automatique;
  const lire = (n, k) => { const v = k === 'timeout' ? (n.parameters && n.parameters.options ? n.parameters.options.timeout : undefined) : n[k]; return v === undefined ? null : v; };
  const n = relu && Array.isArray(relu.nodes) ? relu.nodes.find(x => x.name === prep.etape) : null;
  const pose = !!n && Object.keys(prep.apres || {}).every(k => lire(n, k) === prep.apres[k]);
  const publie = !!relu && relu.active === true && (!relu.activeVersionId || relu.versionId === relu.activeVersionId);
  const base = String(d.action_avant || '').split(/(?:^| · )correction (?:publiée|annulée)/)[0], suite = t => (base ? base + ' · ' : '') + t;
  if (!prep.applicable) texte = '🟠 <b>Correction non appliquée</b>\n' + esc(prep.pourquoi || 'Raison inconnue.');
  else if (!relu) texte = '🟠 <b>n8n a refusé la correction</b>\n' + esc(motif(r.error)) + '\nLe workflow n\'a pas changé.';
  else if (pose && publie && d.geste === 'annuler') { delete memoire.corrections[d.cle]; if (seule) memoire.annulees[cleEtape] = new Date().toISOString(); action = suite('correction annulée depuis Telegram'); texte = '↩ <b>Correction annulée sur « ' + esc(d.workflow) + ' »</b>\n' + esc(prep.fait) + '\nVérifié dans n8n : c\'est la version publiée.' + (seule ? '\nSur cette étape, cette correction ne se publiera plus sans vous : la prochaine fois, elle vous sera proposée.' : ''); }
  else if (pose && publie && d.automatique) { memoire.corrections[d.cle] = { workflow_id: d.workflow_id, etape: prep.etape, avant: prep.avant, quand: new Date().toISOString(), automatique: true }; annulable = true; action = suite('correction publiée automatiquement : ' + prep.fait); texte = '🛠 <b>Corrigé sans attendre : « ' + esc(d.workflow) + ' »</b>\n' + esc(prep.fait) + '\nVérifié dans n8n : la version publiée porte ce réglage. Pas d\'accord ? Le bouton ci-dessous remet tout comme avant.'; }
  else if (pose && publie) { memoire.corrections[d.cle] = { workflow_id: d.workflow_id, etape: prep.etape, avant: prep.avant, quand: new Date().toISOString() }; delete memoire.annulees[cleEtape]; annulable = true; action = suite('correction publiée depuis Telegram : ' + prep.fait); texte = '🛠 <b>Correction publiée sur « ' + esc(d.workflow) + ' »</b>\n' + esc(prep.fait) + '\nVérifié dans n8n : la version publiée porte ce réglage. Pour revenir en arrière, le bouton ci-dessous.'; }
  else if (pose) texte = '🟠 <b>Correction enregistrée, publication non confirmée</b>\nLe brouillon de « ' + esc(d.workflow) + ' » porte la correction, mais n8n n\'a pas confirmé sa publication. Ouvrez le workflow dans n8n pour la publier ou l\'abandonner.';
  else texte = '🟠 <b>Correction non confirmée</b>\nÀ la relecture, « ' + esc(d.workflow) + ' » ne porte pas le réglage attendu. Ouvrez le workflow dans n8n pour vérifier.';
  for (const k of Object.keys(memoire.corrections)) if (Date.now() - Date.parse(memoire.corrections[k].quand) > 30 * 86400000) delete memoire.corrections[k];
} else if (d.quoi === 'rien') { action = 'vu depuis Telegram, aucune action demandée'; texte = 'Noté : aucune action. La panne reste ouverte jusqu\'à la prochaine exécution réussie.'; }
else texte = esc(d.refus);
return [{ json: { cle: d.cle, chat: d.chat, noter: !!action, annulable: annulable, action: action.slice(0, 600), etat: etat, relance_id: relance, texte: texte } }];

// Deux corrections seulement, choisies par une règle écrite, jamais par l'IA. Un seul réglage change, sur une seule étape : tout le reste repart tel qu'il a été lu.
const d = $('Vérifier la demande').first().json, w = $input.first().json || {};
const corrections = $getWorkflowStaticData('global').corrections || {};
const refuser = pourquoi => [{ json: { applicable: false, pourquoi: pourquoi } }];
if (!Array.isArray(w.nodes)) return refuser("n8n n'a pas renvoyé le workflow" + (w.error ? ' : ' + String(w.error.message || w.error.description || w.error).slice(0, 160) : '.'));
if (w.active !== true) return refuser('Ce workflow est en pause : je ne le republie pas à votre place.');
if (w.activeVersionId && w.versionId !== w.activeVersionId) return refuser("Ce workflow a des modifications non publiées : je n'y touche pas. Publiez-les ou abandonnez-les d'abord.");
const REGLAGES = ['retryOnFail', 'maxTries', 'waitBetweenTries', 'timeout'];
const lire = (n, k) => { const v = k === 'timeout' ? (n.parameters && n.parameters.options ? n.parameters.options.timeout : undefined) : n[k]; return v === undefined ? null : v; };
const poser = (n, k, v) => {
  if (k === 'timeout') { n.parameters = n.parameters || {}; n.parameters.options = n.parameters.options || {}; if (v === null) delete n.parameters.options.timeout; else n.parameters.options.timeout = v; }
  else if (v === null) delete n[k]; else n[k] = v;
};
const secondes = ms => Math.round(ms / 1000) + ' s';
const ancienne = d.geste === 'annuler' ? corrections[d.cle] : null;
const etape = ancienne ? ancienne.etape : d.etape;
const n = w.nodes.find(x => x.name === etape);
if (!n) return refuser("L'étape « " + etape + " » n'existe plus dans le workflow.");
let apres = {}, fait = '';
if (d.geste === 'annuler') {
  REGLAGES.forEach(k => { if (k in ancienne.avant) apres[k] = ancienne.avant[k]; });
  fait = "L'étape « " + etape + " » a retrouvé ses réglages d'avant.";
} else if (d.geste === 'tentatives') {
  if (n.retryOnFail === true) return refuser('Les nouvelles tentatives sont déjà activées sur cette étape.');
  apres = { retryOnFail: true, maxTries: 3, waitBetweenTries: 5000 };
  fait = "Nouvelles tentatives activées sur l'étape « " + etape + " » : 3 essais, 5 secondes entre deux.";
} else if (d.geste === 'delai') {
  const actuel = Number(lire(n, 'timeout'));
  if (!/httpRequest$/.test(String(n.type)) || !(actuel > 0)) return refuser("Cette étape n'a pas de délai d'attente réglé : rien à allonger.");
  if (actuel >= 120000) return refuser("Le délai d'attente est déjà de " + secondes(actuel) + ' : je ne vais pas plus loin.');
  apres = { timeout: Math.min(actuel * 2, 120000) };
  fait = "Délai d'attente de l'étape « " + etape + " » passé de " + secondes(actuel) + ' à ' + secondes(apres.timeout) + '.';
} else return refuser('Correction inconnue.');
const avant = {};
Object.keys(apres).forEach(k => { avant[k] = lire(n, k); poser(n, k, apres[k]); });
// L'API de n8n n'accepte que ces réglages de workflow : les autres sont à lui, il les garde.
const PERMIS = ['saveExecutionProgress', 'saveManualExecutions', 'saveDataErrorExecution', 'saveDataSuccessExecution', 'executionTimeout', 'errorWorkflow', 'timezone', 'executionOrder', 'callerPolicy', 'callerIds', 'timeSavedPerExecution', 'availableInMCP'];
const settings = {};
Object.keys(w.settings || {}).forEach(k => { if (PERMIS.indexOf(k) >= 0) settings[k] = w.settings[k]; });
return [{ json: { applicable: true, etape: etape, fait: fait, avant: avant, apres: apres, adresse_n8n: d.adresse_n8n, workflow_id: d.workflow_id, corps: { name: w.name, nodes: w.nodes, connections: w.connections, settings: settings } } }];

// Ce que reçoit le Débogueur automatique quand c'est lui qui a demandé la correction : publiée, ou non. Si elle ne l'est pas, il la proposera avec un bouton.
const c = $('Conclure').first().json;
return [{ json: { publie: c.annulable === true, texte: c.texte } }];
